def count_divisors_with_restrictions(target, min_divisor, max_divisor, excluded):
    divisors = [0] * (target + 1)
    divisors[1] = 1

    for divisor in range(min_divisor, max_divisor + 1):
        if divisor in excluded or divisor > target:
            continue
        for multiple in range(divisor, target + 1, divisor):
            divisors[multiple] += 1

    return divisors[target]

def generate(seed):
    rng = random.Random(seed)

    target = rng.randint(100, 200)
    min_divisor = rng.randint(2, 10)
    max_divisor = rng.randint(15, 25)
    excluded = rng.sample([min_divisor, max_divisor], 1)

    # Find the maximum number of divisors that can multiply to target without exceeding max_divisor.
    max_divisors = 0
    for divisor in range(min_divisor, max_divisor + 1):
        if count_divisors_with_restrictions(target, min_divisor, divisor, excluded) > 0:
            max_divisors = divisor

    answer = count_divisors_with_restrictions(target, min_divisor, max_divisors, excluded)
    assert answer == count_divisors_with_restrictions(target, min_divisor, max_divisors, excluded), f"answer={answer} check={count_divisors_with_restrictions(target, min_divisor, max_divisors, excluded)}"

    problem = (
        f"For an integer \( N \) where \( 1 \leq N \leq {target} \), what is the maximum number of distinct integers \( d \) (with \( {min_divisor} \leq d \leq {max_divisors} \)) such that \( d \) divides \( N \) and \( d \) is not in the set \({excluded}\)? State only the integer."
    )
    return problem, str(answer)

