def max_subset_size(target, min_weight_sum, max_weight_sum):
    if target == 0:
        return 0

    if target < min_weight_sum:
        return -1

    max_size = 0

    for weight_sum in range(min_weight_sum, max_weight_sum + 1):
        if weight_sum <= target:
            remaining_sum = target - weight_sum
            size = max_subset_size(remaining_sum, min_weight_sum, weight_sum - 1)

            if size != -1:
                max_size = max(max_size, size + 1)

    return max_size


def generate(seed):
    rng = random.Random(seed)

    min_weight_sum = rng.randint(3, 10)
    max_weight_sum = rng.randint(20, 30)
    target_sum = rng.randint(15, 30)

    answer = max_subset_size(target_sum, min_weight_sum, max_weight_sum)

    check = -1
    for weight_sum in range(min_weight_sum, max_weight_sum + 1):
        if weight_sum <= target_sum:
            remaining_sum = target_sum - weight_sum
            size = max_subset_size(remaining_sum, min_weight_sum, weight_sum - 1)
            if size != -1:
                check = max(check, 1 + size)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider the weights of a set of objects, where the sum of any subset of weights ranges from {min_weight_sum} to {max_weight_sum} (inclusive). "
        f"What is the maximum number of distinct weights that can be selected such that no subset sum exceeds the target sum {target_sum} and all subset sums sum to exactly {target_sum}? State only the integer."
    )
    return problem, str(answer)

