import itertools

GROUP = "algebra"
SKILL = "counting"

def count_polynomials(target, min_coeff, max_coeff):
    terms = set()
    for coeff in range(min_coeff, max_coeff + 1):
        if coeff > target:
            continue
        for comb in itertools.combinations_with_replacement(range(min_coeff, coeff + 1), target // coeff):
            if sum(comb) == target:
                terms.add(comb)

    return len(terms)

def generate(seed):
    rng = random.Random(seed)

    min_coeff = rng.randint(1, 3)
    max_coeff = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)

    # Find the number of distinct polynomials that can sum to target_sum.
    answer = count_polynomials(target_sum, min_coeff, max_coeff)
    assert answer == count_polynomials(target_sum, min_coeff, max_coeff), f"answer={answer} check={count_polynomials(target_sum, min_coeff, max_coeff)}"

    problem = (
        f"In a polynomial where coefficients can range from {min_coeff} to {max_coeff} (inclusive), "
        f"how many distinct polynomials have terms that sum exactly to {target_sum}? State only the integer."
    )
    return problem, str(answer)

