    min_angle_sum = rng.randint(90, 150)
    max_angle_sum = rng.randint(300, 360)
    target_sum = rng.randint(200, 300)

    angles = sorted(rng.sample(range(60, 181), n))

    # Base case: if target_sum is 0, the set is empty (valid set of size 0)
    if target_sum == 0:
        return problem, str(0)

    # If target_sum is less than min_angle_sum, it's not possible to form such a set
    if target_sum < min_angle_sum:
        return problem, str(-1)

    # Initialize the maximum set size
    max_size = 0

    # Iterate through possible angle sums to find the maximum size
    for angle_sum in range(min_angle_sum, max_angle_sum + 1):
        if angle_sum <= target_sum:
            # Recursively find the maximum size for the remaining sum
            remaining_sum = target_sum - angle_sum
            size = max_size_polygon(remaining_sum, min_angle_sum, angle_sum - 1, angles)

            # Check if the remaining set is valid and update max_size
            if size != -1:
                max_size = max(max_size, size + 1)

    # Independent route: Simulate the maximum size by iterating through possible combinations
    check = -1
    for angle_sum in range(min_angle_sum, max_angle_sum + 1):
        if angle_sum <= target_sum:
            remaining_sum = target_sum - angle_sum
            size = max_size_polygon(remaining_sum, min_angle_sum, angle_sum - 1, angles)
            if size != -1:
                check = max(check, 1 + size)

    assert max_size == check, f"max_size={max_size} check={check}"

    problem = (
        f"Consider the interior angles of a convex {n}-gon with angles ranging from {min_angle_sum} to {max_angle_sum} degrees. What is the maximum number of distinct interior angles that can be selected such that no subset sum exceeds the target sum {target_sum} degrees and all subset sums sum to exactly {target_sum}? State only the integer."
    )
    return problem, str(max_size)

def max_size_polygon(target, min_angle_sum, max_angle_sum, angles):
    if target == 0:
        return 0

    if target < min_angle_sum:
        return -1

    max_size = 0

    for angle_sum in range(min_angle_sum, max_angle_sum + 1):
        if angle_sum <= target:
            remaining_sum = target - angle_sum
            size = max_size_polygon(remaining_sum, min_angle_sum, angle_sum - 1, angles)

            if size != -1:
                max_size = max(max_size, size + 1)

    return max_size

