def count_lines(target, min_length, max_length):
    lines = [0] * (target + 1)
    lines[0] = 1

    for length in range(min_length, max_length + 1):
        if length > target:
            continue
        for i in range(target, length - 1, -1):
            lines[i] += lines[i - length]

    return lines[target]

def generate(seed):
    rng = random.Random(seed)

    min_length = rng.randint(1, 5)
    max_length = rng.randint(10, 20)
    target_sum = rng.randint(5, 10)

    # Find the maximum number of lines that can sum to target_sum without exceeding max_length.
    max_lines = 0
    for length in range(min_length, max_length + 1):
        if count_lines(target_sum, min_length, length) > 0:
            max_lines = length

    answer = count_lines(target_sum, min_length, max_lines)
    assert answer == count_lines(target_sum, min_length, max_lines), f"answer={answer} check={count_lines(target_sum, min_length, max_lines)}"

    problem = (
        f"In a set of lines where the shortest has a length of at least {min_length} units and the longest has a length of at most {max_length} units, "
        f"what is the maximum number of lines that can have a total length of exactly {target_sum} units without exceeding {max_lines} units? State only the integer."
    )
    return problem, str(answer)
